// Demo page logic. webgpu-radar.js is generated by scripts/prepare-site.mjs
// (a self-contained bundle of the library) — run `pnpm build && node
// scripts/prepare-site.mjs` before serving locally.
import { generateReport, probe } from "./webgpu-radar.js";

const $ = (id) => document.getElementById(id);
let lastReport = null;

function outcome(o, render, notRunText) {
  if (!o) return notRunText;
  if (!o.ok) return o.timedOut ? "⏱ timed out" : `❌ ${o.error}`;
  return render(o.value);
}

function show(result) {
  lastReport = generateReport(result);

  const tier = $("tier");
  tier.textContent = result.tier;
  tier.className = result.tier;
  $("meta").textContent = `${result.mode} probe · ${Math.round(result.durationMs)}ms`;

  $("reasons").replaceChildren(
    ...result.reasons.map((r) => Object.assign(document.createElement("li"), { textContent: r })),
  );

  const e = result.environment;
  $("env").textContent = `${e.browser} ${e.browserVersion || "?"} · ${e.os}`;
  $("gpu").textContent = result.gpu
    ? `${result.gpu.vendor || "?"} / ${result.gpu.architecture || "?"}`
    : "no adapter";
  $("wasm").textContent = result.wasm
    ? `simd ${result.wasm.simd ? "✓" : "✗"} · threads ${result.wasm.threads ? "✓" : "✗"}`
    : "not probed";

  const quickNote = "quick mode — run full probe";
  $("b-compile").textContent = outcome(
    result.benchmarks.shaderCompile,
    (v) => `${v.ms.toFixed(1)} ms`,
    "not run",
  );
  $("b-matmul").textContent = outcome(
    result.benchmarks.matmul,
    (v) => `${v.gflops.toFixed(1)} GFLOPS (N=${v.size})`,
    "not run",
  );
  $("b-bandwidth").textContent = outcome(
    result.benchmarks.bandwidth,
    (v) => `${v.gbps.toFixed(2)} GB/s`,
    quickNote,
  );
  $("b-maxbuffer").textContent = outcome(
    result.benchmarks.maxBuffer,
    (v) =>
      `${(v.workingBytes / 1048576).toFixed(0)} MiB works (reported ${(v.reportedBytes / 1048576).toFixed(0)} MiB)`,
    quickNote,
  );
}

async function run(mode) {
  $("run-full").disabled = true;
  try {
    show(await probe({ mode }));
  } catch (err) {
    $("tier").textContent = "error";
    $("tier").className = "unsupported";
    $("meta").textContent = String(err);
  } finally {
    $("run-full").disabled = false;
  }
}

$("run-full").addEventListener("click", () => run("full"));

$("copy").addEventListener("click", async () => {
  if (!lastReport) return;
  await navigator.clipboard.writeText(lastReport.markdown);
  $("copied").style.display = "inline";
  setTimeout(() => {
    $("copied").style.display = "none";
  }, 1500);
});

$("download").addEventListener("click", () => {
  if (!lastReport) return;
  const a = document.createElement("a");
  a.href = URL.createObjectURL(new Blob([lastReport.json], { type: "application/json" }));
  a.download = "webgpu-radar-report.json";
  a.click();
  URL.revokeObjectURL(a.href);
});

run("quick");
